descriptor.controllerScript:
self.onInit = function () {
  const s = self.ctx.$scope;

  s.cpu_usage = '0.00';
  s.cpu_usage_ts = '';
  s.device_temperature = '0.00';
  s.device_temperature_ts = '';

  s.ram_used = 0;
  s.ram_total = 1;
  s.ram_percent = 0;

  s.flash_used = 0;
  s.flash_total = 1;
  s.flash_percent = 0;

  s.rsrp = -140;
  s.rsrp_ts = '';
  s.rsrp_percent = 0;
  s.rssi = -120;
  s.rssi_ts = '';
  s.rssi_percent = 0;

  s.uptime_raw = 0;
  s.uptime_formatted = '';

  s.usage_day = 0;
  s.usage_week = 0;
  s.usage_month = 0;

  s.modem = 'Unknown';
  s.network_type = 'Unknown';
  s.is_online = false;

  // Tailwind slim mode
  if (!document.getElementById('tailwindcss')) {
    window.tailwind = {
      config: {
        safelist: ['grid', 'grid-cols-1', 'sm:grid-cols-2', 'lg:grid-cols-4', 'gap-6', 'text-sm',
          'font-semibold', 'rounded', 'bg-gray-200', 'transition-all', 'duration-300', 'ease-out',
          'text-gray-500', 'text-red-600', 'text-green-500', 'p-4', 'mt-1', 'font-mono'
        ],
        corePlugins: { preflight: false }
      }
    };
    const script = document.createElement('script');
    script.src = 'https://cdn.tailwindcss.com';
    script.id = 'tailwindcss';
    script.onload = () => setTimeout(() => self.ctx.detectChanges(), 50);
    document.head.appendChild(script);
  } else {
    setTimeout(() => self.ctx.detectChanges(), 50);
  }
};

self.onDataUpdated = function () {
  const s = self.ctx.$scope;
  const data = self.ctx.data;

  const getValue = (key) => {
    const entry = data.find(d => d.dataKey.name === key);
    return entry?.data?.length ? entry.data.at(-1)[1] : null;
  };

  const getTS = (key) => {
    const entry = data.find(d => d.dataKey.name === key);
    return entry?.data?.length ? new Date(entry.data.at(-1)[0]).toLocaleTimeString() : '';
  };

  s.rsrp_percent = Math.max(0, Math.min(100, 100 - Math.abs((s.rsrp + 140) * 1.25)));
  s.rssi_percent = Math.max(0, Math.min(100, 100 - Math.abs((s.rssi + 120) * 1.5)));


  // CPU & Temp
  const cpuRaw = getValue('cpu_usage');
  s.cpu_usage = cpuRaw ? (parseFloat(cpuRaw) * 100).toFixed(2) : '0.00';
  s.cpu_usage_ts = getTS('cpu_usage');

  const tempRaw = getValue('device_temperature');
  s.device_temperature = tempRaw ? parseFloat(tempRaw).toFixed(2) : '0.00';
  s.device_temperature_ts = getTS('device_temperature');

  // RAM & Flash
  s.ram_used = parseFloat(getValue('ram_used') || 0);
  s.ram_total = parseFloat(getValue('ram_total') || 1);
  s.ram_percent = ((s.ram_used / s.ram_total) * 100).toFixed(2);

  s.flash_used = parseFloat(getValue('flash_used') || 0);
  s.flash_total = parseFloat(getValue('flash_total') || 1);
  s.flash_percent = ((s.flash_used / s.flash_total) * 100).toFixed(2);

  // RSSI / RSRP
  s.rsrp = parseFloat(getValue('rsrp') || -140);
  s.rsrp_ts = getTS('rsrp');

  s.rssi = parseFloat(getValue('rssi') || -120);
  s.rssi_ts = getTS('rssi');

  // Uptime
  s.uptime_raw = parseFloat(getValue('uptime') || 0);
  if (s.uptime_raw > 0) {
    const h = Math.floor(s.uptime_raw / 3600);
    const m = Math.floor((s.uptime_raw % 3600) / 60);
    s.uptime_formatted = `${h}h ${m}m`;
  } else {
    s.uptime_formatted = '0h';
  }

  // Data Usage
  s.usage_day = (parseFloat(getValue('data_usage_total_day') || 0) / 1024).toFixed(2);
  s.usage_week = (parseFloat(getValue('data_usage_total_week') || 0) / 1024).toFixed(2);
  s.usage_month = (parseFloat(getValue('data_usage_total_month') || 0) / 1024).toFixed(2);

  // Modem / Network
  s.modem = getValue('modem') || 'Unknown';
  s.network_type = getValue('network_type') || 'Unknown';
  s.is_online = getValue('is_online') === true || getValue('is_online') === 'true';

  self.ctx.detectChanges();
};

self.onDestroy = function () {
  console.log('🧹 Widget destroyed');
};

